import java.util.*;

class Solution {
    public int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) return n;
        int best = 1;
        for (int i = 0; i < n; i++) {
            Map<String, Integer> slopes = new HashMap<>();
            for (int j = i + 1; j < n; j++) {
                String key = direction(points[i], points[j]);
                int count = slopes.merge(key, 1, Integer::sum);
                best = Math.max(best, count + 1);
            }
        }
        return best;
    }

    private String direction(int[] a, int[] b) {
        int dx = b[0] - a[0];
        int dy = b[1] - a[1];
        if (dx == 0) return "0/1";
        if (dy == 0) return "1/0";
        int g = gcd(Math.abs(dx), Math.abs(dy));
        dx /= g;
        dy /= g;
        if (dx < 0) {
            dx = -dx;
            dy = -dy;
        }
        return dx + "/" + dy;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

import java.util.*;

class Solution {
    public int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) return n;
        int best = 2;
        for (int i = 0; i < n; i++) {
            List<String> directions = new ArrayList<>();
            for (int j = i + 1; j < n; j++) {
                directions.add(direction(points[i], points[j]));
            }
            Collections.sort(directions);
            int run = 0;
            String previous = null;
            for (String key : directions) {
                if (key.equals(previous)) {
                    run++;
                } else {
                    previous = key;
                    run = 1;
                }
                best = Math.max(best, run + 1);
            }
        }
        return best;
    }

    private String direction(int[] a, int[] b) {
        int dx = b[0] - a[0];
        int dy = b[1] - a[1];
        if (dx == 0) return "0/1";
        if (dy == 0) return "1/0";
        int g = gcd(Math.abs(dx), Math.abs(dy));
        dx /= g;
        dy /= g;
        if (dx < 0) {
            dx = -dx;
            dy = -dy;
        }
        return dx + "/" + dy;
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

class Solution {
    public int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) return n;
        int best = 2;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int count = 0;
                for (int k = 0; k < n; k++) {
                    long dx1 = points[j][0] - points[i][0];
                    long dy1 = points[j][1] - points[i][1];
                    long dx2 = points[k][0] - points[i][0];
                    long dy2 = points[k][1] - points[i][1];
                    if (dx1 * dy2 == dy1 * dx2) {
                        count++;
                    }
                }
                best = Math.max(best, count);
            }
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) return n;
        Map<String, Set<Integer>> lines = new HashMap<>();
        int best = 2;
        for (int i = 0; i < n; i++) {
            long x1 = points[i][0];
            long y1 = points[i][1];
            for (int j = i + 1; j < n; j++) {
                long x2 = points[j][0];
                long y2 = points[j][1];
                long a = y2 - y1;
                long b = x1 - x2;
                long c = -(a * x1 + b * y1);
                long g = gcd(Math.abs(a), gcd(Math.abs(b), Math.abs(c)));
                if (g != 0) {
                    a /= g;
                    b /= g;
                    c /= g;
                }
                if (a < 0 || (a == 0 && b < 0)) {
                    a = -a;
                    b = -b;
                    c = -c;
                }
                String key = a + "/" + b + "/" + c;
                Set<Integer> set = lines.computeIfAbsent(key, ignored -> new HashSet<>());
                set.add(i);
                set.add(j);
                best = Math.max(best, set.size());
            }
        }
        return best;
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}
